"""Resilient RPC client utilizing tokenized retry budgeting."""

from typing import Callable, Any
from policy import RetryPolicy
from budget import RetryBudget


class ResilientClient:
    def __init__(self, budget: RetryBudget, policy: RetryPolicy):
        self.budget = budget
        self.policy = policy

    def execute_with_retry(self, operation: Callable[[], Any]) -> Any:
        attempts = 0
        while True:
            self.budget.record_attempt()
            try:
                return operation()
            except Exception as exc:
                attempts += 1
                if attempts > self.policy.max_retries or not self.budget.can_retry():
                    raise exc
                self.budget.spend_retry_token()

reference_fix.budget.py:
"""Client-side token bucket retry budget."""

class RetryBudget:
    def __init__(self, capacity: float = 10.0, initial_tokens: float = 5.0, token_cost: float = 1.0):
        self.capacity = capacity
        self.tokens = initial_tokens
        self.token_cost = token_cost
        self.total_attempts = 0

    def record_attempt(self) -> None:
        self.total_attempts += 1

    def record_success(self) -> None:
        # Tokens only replenish on genuine downstream success
        self.tokens = min(self.capacity, self.tokens + 0.2)

    def can_retry(self) -> bool:
        return self.tokens >= self.token_cost

    def spend_retry_token(self) -> bool:
        if self.tokens >= self.token_cost:
            self.tokens -= self.token_cost
            return True
        return False

